func crystallineFnStorageInitializeStorage(this js.Value, args []js.Value) (result any) {
	defer crystallineRecover(&result)

	if len(args) != 6 {
		return crystallineFail("InitializeStorage: expected 6 arguments, got " + strconv.Itoa(len(args)))
	}

	return crystallinePromise(func() any {
		a0 := func(p0 string, p1 string) []storage.DirEntry {
			crystallineCallbackResult := crystallineAwait(args[0].Invoke(string(p0), string(p1)))

			crystallineConverted, err := crystallineToSliceOfStorageDirEntry(crystallineCallbackResult)
			if err != nil {
				panic("storage.InitializeStorage: callback result: " + err.Error())
			}

			return crystallineConverted
		}

		a1 := func(p0 string, p1 string) []byte {
			crystallineCallbackResult := crystallineAwait(args[1].Invoke(string(p0), string(p1)))

			crystallineConverted, err := crystallineToBytes(crystallineCallbackResult)
			if err != nil {
				panic("storage.InitializeStorage: callback result: " + err.Error())
			}

			return crystallineConverted
		}

		a2 := func(p0 string, p1 string, p2 []byte) {
			crystallineAwait(args[2].Invoke(string(p0), string(p1), crystallineBytes(p2)))
		}

		a3 := func(p0 string, p1 string) bool {
			crystallineCallbackResult := crystallineAwait(args[3].Invoke(string(p0), string(p1)))

			crystallineConverted, err := crystallineToBool(crystallineCallbackResult)
			if err != nil {
				panic("storage.InitializeStorage: callback result: " + err.Error())
			}

			return crystallineConverted
		}

		a4 := func(p0 string, p1 string) {
			crystallineAwait(args[4].Invoke(string(p0), string(p1)))
		}

		a5 := func(p0 string, p1 string) {
			crystallineAwait(args[5].Invoke(string(p0), string(p1)))
		}

		storage.InitializeStorage(a0, a1, a2, a3, a4, a5)

		return nil
	})
}

